<?php

declare(strict_types=1);

namespace Database\Seeders;

use App\Core\Database;

final class RolePermissionSeeder
{
    /** @var array<int, array{name: string, label: string, is_system: bool}> */
    private const ROLES = [
        ['name' => 'super-admin', 'label' => 'Super Admin', 'is_system' => true],
        ['name' => 'editor', 'label' => 'Editor', 'is_system' => true],
        ['name' => 'author', 'label' => 'Penulis', 'is_system' => true],
    ];

    /** Baseline non-module permissions. Module permissions are generated by the DB trigger. */
    private const BASE_PERMISSIONS = [
        ['key_name' => 'articles.view', 'group_name' => 'Articles', 'label' => 'Lihat Artikel'],
        ['key_name' => 'articles.create', 'group_name' => 'Articles', 'label' => 'Tambah Artikel'],
        ['key_name' => 'articles.edit', 'group_name' => 'Articles', 'label' => 'Edit Artikel'],
        ['key_name' => 'articles.delete', 'group_name' => 'Articles', 'label' => 'Hapus Artikel'],
        ['key_name' => 'articles.publish', 'group_name' => 'Articles', 'label' => 'Publish Artikel'],
        ['key_name' => 'pages.view', 'group_name' => 'Pages', 'label' => 'Lihat Halaman'],
        ['key_name' => 'pages.create', 'group_name' => 'Pages', 'label' => 'Tambah Halaman'],
        ['key_name' => 'pages.edit', 'group_name' => 'Pages', 'label' => 'Edit Halaman'],
        ['key_name' => 'pages.delete', 'group_name' => 'Pages', 'label' => 'Hapus Halaman'],
        ['key_name' => 'media.view', 'group_name' => 'Media', 'label' => 'Lihat Media'],
        ['key_name' => 'media.upload', 'group_name' => 'Media', 'label' => 'Upload Media'],
        ['key_name' => 'media.delete', 'group_name' => 'Media', 'label' => 'Hapus Media'],
        ['key_name' => 'menus.manage', 'group_name' => 'Menu', 'label' => 'Kelola Menu'],
        ['key_name' => 'theme.manage', 'group_name' => 'Theme', 'label' => 'Kelola Theme & Widget'],
        ['key_name' => 'users.manage', 'group_name' => 'Users', 'label' => 'Kelola Pengguna & Role'],
        ['key_name' => 'settings.manage', 'group_name' => 'Settings', 'label' => 'Kelola Pengaturan'],
    ];

    public function run(Database $db): void
    {
        foreach (self::ROLES as $role) {
            $db->execute(
                'INSERT IGNORE INTO roles (name, label, is_system) VALUES (:name, :label, :is_system)',
                $role
            );
        }

        foreach (self::BASE_PERMISSIONS as $permission) {
            $db->execute(
                'INSERT IGNORE INTO permissions (key_name, group_name, label) VALUES (:key_name, :group_name, :label)',
                $permission
            );
        }

        // super-admin gets every permission that currently exists (base + module-generated).
        $db->execute(<<<SQL
            INSERT IGNORE INTO role_permissions (role_id, permission_id)
            SELECT r.id, p.id
            FROM roles r
            CROSS JOIN permissions p
            WHERE r.name = 'super-admin'
        SQL);

        // editor: can manage content + media, but not users/roles.
        $db->execute(<<<SQL
            INSERT IGNORE INTO role_permissions (role_id, permission_id)
            SELECT r.id, p.id
            FROM roles r
            CROSS JOIN permissions p
            WHERE r.name = 'editor'
              AND p.key_name NOT LIKE 'users.%'
        SQL);

        // author: view + create own content, no delete/publish/user management.
        $db->execute(<<<SQL
            INSERT IGNORE INTO role_permissions (role_id, permission_id)
            SELECT r.id, p.id
            FROM roles r
            CROSS JOIN permissions p
            WHERE r.name = 'author'
              AND (p.key_name LIKE '%.view' OR p.key_name LIKE '%.create' OR p.key_name = 'media.upload')
        SQL);
    }
}
